-- Retain view permissions and projection types. Rollback by restoring the previous view definition; score runs and data remain untouched.
CREATE OR REPLACE VIEW public.v_admin_candidate_index AS
SELECT m.id AS match_id,m.application_id,m.candidate_profile_id,m.position_id,m.organization_id,o.name AS org_name,p.title AS position_title,cp.full_name,cp.email,cp.phone,cp.country,cp.region,cp.city,cp.location,m.stage::text AS stage,m.admin_status::text AS admin_status,m.canonical_state::text AS canonical_state,m.client_visibility::text AS client_visibility,m.processing_state::text AS processing_state,m.eligibility_status::text AS eligibility_status,m.recommendation::text AS recommendation,m.integrity_status::text AS integrity_status,m.evidence_confidence,m.contact_released_at,m.contact_released_at IS NOT NULL AS contact_released,m.created_at,m.updated_at,a.applied_at,a.source,a.source_kind::text AS source_kind,a.source_channel,sr.id AS score_run_id,
(CASE WHEN m.processing_state::text='ocr_required' OR m.processing_error_code IN ('cv_employment_history_missing','cv_missing','cv_file_missing','cv_unparsed') THEN NULL ELSE COALESCE(ov.approved_score,sr.score) END)::numeric(6,2) AS score,
(CASE WHEN m.processing_state::text='ocr_required' OR m.processing_error_code IN ('cv_employment_history_missing','cv_missing','cv_file_missing','cv_unparsed') THEN NULL ELSE COALESCE(ov.approved_score,sr.final_score) END)::numeric(6,2) AS final_score,
sr.fit_label,sr.fit_band,sr.confidence,sr.contradiction_status,public.score_band(CASE WHEN m.processing_state::text='ocr_required' OR m.processing_error_code IN ('cv_employment_history_missing','cv_missing','cv_file_missing','cv_unparsed') THEN NULL ELSE COALESCE(ov.approved_score,sr.final_score,sr.score) END)::text AS score_band,
m.integrity_status::text<>'ok' OR sr.contradiction_status=ANY(ARRAY['disqualifying_answer','contradiction_found']) OR m.eligibility_status::text='ineligible' OR m.processing_state::text=ANY(ARRAY['failed','provider_blocked','manual_review_required','ocr_required']) AS has_critical_flag,COALESCE(m.is_test_record,false) OR COALESCE(p.is_test_record,false) OR COALESCE(o.is_test_record,false) OR COALESCE(cp.is_test_record,false) AS is_test_record,
lower(COALESCE(cp.full_name,'') || ' ' || COALESCE(cp.email,'') || ' ' || COALESCE(cp.phone,'') || ' ' || COALESCE(p.title,'') || ' ' || COALESCE(o.name,'') || ' ' || COALESCE(cp.city,'') || ' ' || COALESCE(cp.country,'')) AS search_text,sr.completed_at AS scored_at,sr.engine_version AS scored_engine_version,sr.input_hash AS scored_input_hash,cp.updated_at AS profile_updated_at,p.updated_at AS brief_updated_at,p.status::text AS position_status,m.score_stale,m.score_stale_at,m.score_stale_reasons,COALESCE(sr.final_score,sr.score) AS automated_score,ov.approved_score AS override_score,ov.reason AS override_reason
FROM public.candidate_matches m JOIN public.positions p ON p.id=m.position_id JOIN public.organizations o ON o.id=m.organization_id LEFT JOIN public.candidate_profiles cp ON cp.id=m.candidate_profile_id LEFT JOIN public.applications a ON a.id=m.application_id LEFT JOIN public.score_runs sr ON sr.id=COALESCE(m.approved_score_run_id,m.current_score_run_id)
LEFT JOIN LATERAL (SELECT sd.approved_score,sd.reason FROM public.score_decisions sd WHERE sd.candidate_match_id=m.id AND sd.score_run_id=sr.id AND sd.decision_type='override' ORDER BY sd.created_at DESC,sd.id DESC LIMIT 1) ov ON true;
